class LRUCache {
  int cap; std::unordered_map<int, Node*> m;
  Node head, tail;
  void touch(Node* n){ /* 摘除并移到 tail 前 */ }
public:
  LRUCache(int c): cap(c){ head.next=&tail; tail.prev=&head; }
  int get(int k){ auto it=m.find(k); if(it==m.end()) return -1; touch(it->second); return it->second->val; }
  void put(int k,int v){ /* find/touch/满则删 head.next/新节点插 tail 前 */ }
};

#include <queue><thread><mutex><condition_variable><functional><future>
class ThreadPool {
  std::queue<std::function<void()>> q; std::mutex m; std::condition_variable cv;
  std::vector<std::thread> ws; bool stop=false;
public:
  ThreadPool(size_t n){ for(size_t i=0;i<n;++i) ws.emplace_back([this]{
    for(;;){ std::function<void()> f; { std::unique_lock<std::mutex> lk(m);
      cv.wait(lk,[&]{ return stop || !q.empty(); });
      if(stop && q.empty()) return; f=std::move(q.front()); q.pop(); }
      f(); } }); }
  template<class F> auto submit(F&& f){ auto p=std::make_shared<std::packaged_task<decltype(f())()>>(std::forward<F>(f));
    auto r=p->get_future(); { std::lock_guard<std::mutex> lk(m); q.push([p]{ (*p)(); }); } cv.notify_one(); return r; }
  void shutdown(){ { std::lock_guard<std::mutex> lk(m); stop=true; } cv.notify_all(); for(auto&t:ws) t.join(); }
};
